export type Story = {id:string;slug:string;title:string;category:string;date:string;description:string;image:string;imageCredit:string;body:string[];readingTime:string;sourceIds:string[];driverIds:string[];carIds:string[];officialUrl:string;verifiedAt:string};
const story=(d:Omit<Story,"slug"|"imageCredit"|"readingTime"|"officialUrl"|"verifiedAt">):Story=>({...d,slug:d.id,imageCredit:d.image?"Aston Martin Aramco Formula One Team. Editorial reference.":"",readingTime:"2 min read",officialUrl:sources.find(s=>s.id===d.sourceIds[0])?.url??"https://www.astonmartinf1.com",verifiedAt:verificationDate});
export const stories:Story[] = [
  story({id:"a-new-way-of-thinking",title:"A new way of thinking.",category:"Engineering",date:"2026-02-09",description:"The AMR26 brings a new chassis rulebook and the Honda works partnership into one programme.",image:"/images/hero.jpg",body:["A new chassis and a new power unit must work as one. For Aston Martin, the 2026 reset brought that integration into sharper focus with Honda as its works partner.","The AMR26 is the first Aston Martin challenger shaped by Adrian Newey’s design philosophy, with Enrico Cardile as Chief Technical Officer. Its Honda RA626H belongs to the new generation of Formula One power units.","This garage uses an illustrative model to explain principles. Precise aerodynamic surfaces, internal packaging and performance measurements remain the team’s engineering work."],sourceIds:["amr26","honda-2026"],driverIds:["fernando-alonso","lance-stroll"],carIds:["amr26"]}),
  story({id:"the-space-to-make-progress",title:"The space to make progress.",category:"Inside the team",date:"2025-05-22",description:"A technology campus brings design, manufacture and aerodynamic development closer together.",image:"/images/factory.jpg",body:["A racing car is the product of thousands of decisions, and the distance between those decisions matters. The AMR Technology Campus gives the team a shared base for its development work.","The team announced that its new wind tunnel came online in March 2025. Its CoreWeave partnership connects computing capability with the engineering process.","A wind tunnel is a controlled model of the problem. Teams compare its findings with simulation and circuit observations; this site does not reproduce confidential test data."],sourceIds:["wind-tunnel","manufacturing"],driverIds:[],carIds:["amr25","amr26"]}),
  story({id:"made-one-piece-at-a-time",title:"Made, one piece at a time.",category:"Craft",date:"2025-02-23",description:"Behind every finished surface is a chain of design, manufacturing, inspection and assembly.",image:"/images/factory.jpg",body:["The completed car is the visible end of a much longer manufacturing story. Components must be designed, made, checked and assembled into systems that work together.","Aston Martin’s official INSIDER film follows the work behind an F1 car. Watch the original film for access to the people and processes inside the factory.","The editorial diagrams here explain component roles. They do not claim access to factory drawings, proprietary tolerances or manufacturing performance figures."],sourceIds:["manufacturing"],driverIds:[],carIds:["amr25"]}),
  story({id:"eight-times-on-the-podium",title:"Eight times on the podium.",category:"People",date:verificationDate,description:"Fernando Alonso’s first season in green gave Aston Martin eight podium finishes and a new sense of possibility.",image:"/images/alonso.jpg",body:["Fernando Alonso’s arrival coincided with a major step forward. In 2023 he scored eight podium finishes and ended the season fourth in the Drivers’ Championship.","He contributed 206 of the team’s 280 points. Lance Stroll added 74 as Aston Martin finished fifth among the constructors.","These are Aston Martin results. Fernando’s two World Championships remain part of his earlier Renault career."],sourceIds:["alonso","drivers-2023","standings-2023"],driverIds:["fernando-alonso","lance-stroll"],carIds:["amr23"]}),
  story({id:"a-point-of-departure",title:"A point of departure.",category:"Heritage",date:"1959-05-31",description:"The DBR4 entered a sport already changing around it. The original chapter deserves its own record.",image:"/images/heritage.jpg",body:["Aston Martin’s first World Championship Formula One appearance came at Zandvoort in 1959. Roy Salvadori and Carroll Shelby both retired in the DBR4.","The marque’s front-engined challenger arrived as mid-engined designs were changing the sport. Four championship events followed in 1959, with a best result of sixth.","The story is distinct from Aston Martin’s sports-car successes, and from the Silverstone organisation that later became the modern Aston Martin team."],sourceIds:["1959-ned","dbr4","original-era"],driverIds:["roy-salvadori","carroll-shelby"],carIds:["dbr4"]}),
  story({id:"singapore-after-dark",title:"Under the Singapore lights.",category:"Race report",date:"2026-10-11",description:"The latest completed round in this verified season snapshot: Alonso sixteenth, Stroll retired.",image:"/images/race.jpg",body:["The Singapore Grand Prix closed the latest completed race weekend in this archive snapshot. Fernando Alonso finished sixteenth and Lance Stroll retired.","The team leaves the round with seven constructor points and tenth place in the standings. The next scheduled event is the United States Grand Prix in Austin, 23–25 October.","Read the official report for the drivers’ reactions and the full weekend account. Results here are a dated snapshot; there is no live timing connection."],sourceIds:["singapore-2026","standings-2026","austin-2026"],driverIds:["fernando-alonso","lance-stroll"],carIds:["amr26"]}),
  story({id:"the-work-before-the-weekend",title:"The work before the weekend.",category:"Driver development",date:verificationDate,description:"Racecraft develops in the simulator, the briefing room and the work between events.",image:"/images/factory.jpg",body:["The race pairing is the most visible part of a larger driver group. Jak Crawford’s 2026 third-driver role includes race operations support and simulator work.","Stoffel Vandoorne contributes as simulator, test and reserve driver. Jessica Hawkins leads the team’s F1 ACADEMY involvement, while the Driver Academy supports emerging talent.","Testing, reserve duties and academy racing are recorded separately from Formula One race starts throughout this archive."],sourceIds:["crawford","vandoorne","academy","hawkins"],driverIds:["jak-crawford","stoffel-vandoorne","jessica-hawkins","mari-boya","mathilda-paatz"],carIds:["amr26"]}),
];

